from pathlib import Path
import gzip,json,hashlib,collections
ROOT=Path(__file__).resolve().parents[1]/'shot250-windmill'
OUT=Path(__file__).resolve().parent
IDS=['baseline','wheel-left025','wheel-right025','wheel-up025','wheel-down025']
def outcomes(rows):return dict(collections.Counter(r['outcome'] for r in rows))
def group(rows,predicate):
 selected=[r for r in rows if predicate(r)]
 return {'balls':len(selected),'outcomes':outcomes(selected)}
def pin_events(row,ids):return [p for p in row['pinContacts'] if p['pinId'] in ids]
results=[];base_shots=None
for case in IDS:
 d=ROOT/(case+'-phase0');compressed=(d/'result.json.gz').read_bytes();expanded=gzip.decompress(compressed);r=json.loads(expanded);manifest=json.loads((d/'raw-manifest.json').read_text())[0];prov=json.loads((d/'provenance.json').read_text());assert hashlib.sha256(compressed).hexdigest()==manifest['compressedSHA'];assert hashlib.sha256(expanded).hexdigest()==manifest['expandedSHA'];assert prov['success'] and prov['sourceUnchanged'] and prov['gitUnchanged'];assert prov['commit']==prov['endCommit'];rows=r['s8ShotObservation']['rows'];assert len(rows)==250
 shots=[e for e in r['events'] if e['type']=='shot'];base_shots=shots if base_shots is None else base_shots;deltas=[e['time']-b['time'] for e,b in zip(shots,base_shots)];different=[i for i,v in enumerate(deltas) if abs(v)>1e-9]
 wm=[v for v in rows if v['firstWindmillContact']]
 item={'id':case,'sourceSHA':r['sourceSHA'],'commit':prov['commit'],'compressedSHA':manifest['compressedSHA'],'expandedSHA':manifest['expandedSHA'],'shots':r['physical']['shots'],'end':r['end'],'actualFiringSeconds':r['conditions']['actualFiringSeconds'],'maxGap':r['observation']['observedFiringGap'],'allLayerWindmillRole':r['endDiagnostics']['roleFlow']['windmill'],'firstFrontWindmill':{'balls':len(wm),'outcomes':outcomes(wm),'vxDirections':{name:group(wm,lambda v,fn=fn:fn(v['firstWindmillContact']['vx'])) for name,fn in [('left',lambda x:x<-1e-9),('right',lambda x:x>1e-9),('zero',lambda x:abs(x)<=1e-9)]},'firstPinBeforeWindmillIds':dict(collections.Counter(str(v['firstPinContact']['pinId']) if v['firstPinContact'] and v['firstPinContact']['time']<=v['firstWindmillContact']['time'] else 'none-before' for v in wm))},'actualPin1or2Impulse':group(rows,lambda v:bool(pin_events(v,{1,2}))),'actualAnyRoadPinImpulse':group(rows,lambda v:bool(pin_events(v,set(range(1,27))))),'terminalRectangle':group(rows,lambda v:bool(v['route']['terminalFirstEntry'])),'firstDescendingZones':{zone:group(rows,lambda v,z=zone:(v['route']['firstDescending'] or {}).get('zone','unobserved')==z) for zone in ['left','envelope','right','unobserved']},'windmillBeforeFirstRoadPin':group(rows,lambda v:bool(v['firstWindmillContact'] and pin_events(v,set(range(1,27))) and v['firstWindmillContact']['time']<min(p['time'] for p in pin_events(v,set(range(1,27)))))),'windmillAfterOrSameFirstRoadPin':group(rows,lambda v:bool(v['firstWindmillContact'] and pin_events(v,set(range(1,27))) and v['firstWindmillContact']['time']>=min(p['time'] for p in pin_events(v,set(range(1,27)))))),'windmillThenTerminal':group(rows,lambda v:bool(v['firstWindmillContact'] and v['route']['terminalFirstEntry'] and v['firstWindmillContact']['time']<v['route']['terminalFirstEntry']['time'])),'routeMetrics':r['routeMetrics'],'shotScheduleVsBaseline':{'differentTimes':len(different),'firstDifferentBallId':shots[different[0]]['ballId'] if different else None,'firstDeltaSeconds':deltas[different[0]] if different else None,'maximumAbsoluteDeltaSeconds':max(map(abs,deltas)),'sameShotIds':all(e['ballId']==b['ballId'] for e,b in zip(shots,base_shots))}}
 results.append(item)
report={'scope':'Read-only existing five phase0 runs. Group outcome sets overlap and must not be summed. First per-pin successful impulse is not last actual collision. Windmill directions are velocities at the first successful front windmill record, not guaranteed sustained exit directions. Road entry is operationally pin1/2 successful impulse; lack of impulse is not lack of geometric arrival. Terminal is existing rectangle x355..400/y824..870 SOURCE. Same shot IDs across runs do not establish same trajectories; pair collisions and schedule can diverge. No trials or product/source edits.','cases':results}
(OUT/'summary.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
for x in results:
 print(x['id'], 'heso',x['end']['counts']['start'],'wm',x['allLayerWindmillRole']['balls'],x['firstFrontWindmill']['balls'],'vx',[(k,v['balls']) for k,v in x['firstFrontWindmill']['vxDirections'].items()],'entry',x['actualPin1or2Impulse'],'road',x['actualAnyRoadPinImpulse'],'terminal',x['terminalRectangle'],'zones',x['firstDescendingZones'],'schedule',x['shotScheduleVsBaseline'],'wmBefore',x['windmillBeforeFirstRoadPin']['balls'],'wmAfter',x['windmillAfterOrSameFirstRoadPin']['balls'])
